import { build } from 'esbuild';
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const result = await build({ absWorkingDir: root, entryPoints: ['client.mjs'], bundle: true,
  format: 'cjs', platform: 'browser', target: 'es2022', charset: 'utf8', external: ['react'], write: false, logLevel: 'silent' });
if (result.warnings.length) throw new Error(result.warnings.map(x => x.text).join('\n'));
const text = [
  '// Generated by scripts/build-client.mjs for the DSH classic-script module loader.',
  'window.__ModuleLoader__.load({ id: "dsh-magpie-catalog-sync", factory: (require) => {',
  'const module = { exports: {} };', result.outputFiles[0].text,
  'return Object.defineProperty({ ...module.exports }, Symbol.toStringTag, { value: "Module" });',
  '} });', '',
].join('\n');
const file = path.join(root, 'client.js');
if (process.argv.includes('--check')) {
  if (await fs.readFile(file, 'utf8') !== text) throw new Error('client.js 已过期，请运行 npm run build');
} else await fs.writeFile(file, text);
